+                    }
+                    Instant tstamp = ZonedDateTime.parse(String.valueOf(e.get(LoggingAuditTrail.TIMESTAMP)), TSTAMP_FORMATTER).toInstant();
+                    if (tstamp.isBefore(start)) {
+                        return false;
+                    }
+                    return true;
